-- CRaMer v2 schema (applied to Supabase project as migration crm_v1_schema). No data in this file.
create table public.contacts (id text primary key, email text, name text, org text, linkedin text, status text not null default 'pending' check (status in ('pending','sent','bounced','rerouted')), dnc boolean not null default false, updated_at timestamptz not null default now());
create table public.deals (id text primary key, contact_id text not null references public.contacts(id) on delete cascade, title text, stage text not null default 'Lead' check (stage in ('Lead','Contacted','Replied','Meeting','Negotiation','Won','Lost')), value numeric default 0, updated_at timestamptz not null default now());
create table public.events (id bigserial primary key, contact_id text not null references public.contacts(id) on delete cascade, channel text, kind text, date text, summary text, source_file text);
create table public.queue_items (id text primary key, contact_id text not null references public.contacts(id) on delete cascade, deal_id text references public.deals(id) on delete set null, type text check (type in ('ask','commitment_by_me','commitment_by_them','record_fact')), summary text, quote text, source text, source_link text, source_timestamp text, owner text, due_date date, status text not null check (status in ('Open','Drafted','Waiting','Blocked','Closed','Unknown')), closure_action text, draft_id text, last_checked_at text, sources jsonb not null default '[]'::jsonb, updated_at timestamptz not null default now());
create table public.edits (id bigserial primary key, entity text not null check (entity in ('deal','contact','queue_item')), entity_id text not null, field text not null, old_value text, new_value text, created_at timestamptz not null default now());
create index on public.deals(contact_id); create index on public.events(contact_id); create index on public.queue_items(contact_id); create index on public.edits(entity, entity_id);
alter table public.contacts enable row level security; alter table public.deals enable row level security; alter table public.events enable row level security; alter table public.queue_items enable row level security; alter table public.edits enable row level security;
-- No policies: only the service role (server-side) can read/write.
revoke all on public.contacts, public.deals, public.events, public.queue_items, public.edits from anon, authenticated;
revoke all on sequence public.events_id_seq, public.edits_id_seq from anon, authenticated;
